#include <cmath>
#include <stdexcept>
#include "Car.hpp"
#include <algorithm>
#include <iostream>
#include <iomanip>
#include <memory>
#include <stdexcept>
#include <cstdlib>
#ifdef _WIN32
#include <direct.h>
#include <windows.h>
#endif
namespace car {
int run(const Options& o){
 cv::setNumThreads(o.threads);_mkdir(o.output.c_str());_mkdir((o.output+"/evidence").c_str());bool camera=o.source.size()==1&&o.source[0]>='0'&&o.source[0]<='9';cv::VideoCapture cap;if(camera)cap.open(std::atoi(o.source.c_str()),cv::CAP_DSHOW);else cap.open(o.source);
 if(!cap.isOpened())throw std::runtime_error("Cannot open camera/video: "+o.source);cap.set(cv::CAP_PROP_BUFFERSIZE,1);if(camera)cap.set(cv::CAP_PROP_FPS,o.fps);double sourceFps=cap.get(cv::CAP_PROP_FPS);if(!std::isfinite(sourceFps)||sourceFps<1||sourceFps>240)sourceFps=30;
 std::unique_ptr<Pipeline> sync;std::unique_ptr<Worker> worker;if(o.offline)sync.reset(new Pipeline(o));else worker.reset(new Worker(o));
 std::ofstream csv(o.output+"/tracks.csv"),ocr(o.output+"/recognition.jsonl");if(!csv||!ocr)throw std::runtime_error("Cannot write output files");csv<<"frame,time_s,track_id,vehicle_type,plate,characters,numbers,plate_confidence,vehicle_confidence,stable,plate_status,plate_source,observed_time_s,last_read_text,vehicle_observed_time_s,reacquisitions\n";
 Tracker tracker;cv::VideoWriter recording;cv::Mat image;int frames=0,inferences=0,stale=0,previewFrames=0;double nextPreview=0;std::vector<double> latency;auto start=std::chrono::steady_clock::now();
 while((!o.maxFrames||frames<o.maxFrames)&&cap.read(image)){
  double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();double timestamp=camera?elapsed:frames/sourceFps;if(frames==0)cv::imwrite(o.output+"/input_first.jpg",image);Result result;bool have=false;
  if(o.offline){if(frames%o.detectorEvery==0){auto begin=std::chrono::steady_clock::now();result.detections=sync->detect(image);result.frame=frames;result.timestamp=timestamp;result.seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();have=true;}}
  else{if(frames%o.detectorEvery==0)worker->submit(image,frames,timestamp);have=worker->take(result);if(have&&timestamp-result.timestamp>o.maxAge){++stale;have=false;}}
  if(have){++inferences;latency.push_back(result.seconds*1000);tracker.predict(result.timestamp);tracker.update(result.detections,result.timestamp);int readingIndex=0;for(const auto& d:result.detections)if(!d.plate.text.empty()){std::string evidenceImage="evidence/frame_"+std::to_string(result.frame)+"_read_"+std::to_string(readingIndex++)+".png";if(d.plateImage.empty()||!cv::imwrite(o.output+"/"+evidenceImage,d.plateImage))throw std::runtime_error("Cannot save OCR evidence crop");ocr<<"{\"frame\":"<<result.frame<<",\"vehicle_type\":"<<jsonText(typeName(d.category))<<",\"plate\":"<<jsonText(d.plate.text)<<",\"evidence_source\":"<<jsonText(d.plateSource)<<",\"evidence_image\":"<<jsonText(evidenceImage)<<",\"observation_time_s\":"<<result.timestamp<<",\"plate_box\":["<<d.plateBox.x<<','<<d.plateBox.y<<','<<d.plateBox.width<<','<<d.plateBox.height<<"],\"character_text\":"<<jsonText(characters(d.plate.text))<<",\"numbers\":"<<jsonText(numbers(d.plate.text))<<",\"confidence\":"<<d.plate.confidence<<",\"symbol_confidence_source\":\""<<(o.ocrLanguages=="latin"?"glyph_or_ctc":"line_mean")<<"\",\"characters\":[";auto symbols=textSymbols(d.plate.text);for(size_t i=0;i<symbols.size();++i){if(i)ocr<<',';ocr<<"{\"value\":"<<jsonText(symbols[i].value)<<",\"kind\":\""<<(symbols[i].number?"number":"character")<<"\",\"confidence\":"<<(i<d.plate.characterConfidence.size()?d.plate.characterConfidence[i]:d.plate.confidence)<<'}';}ocr<<"]}\n";}}
  Tracker view=tracker.project(timestamp);
  for(const auto& t:view.tracks())if(t.hits>=2)csv<<frames<<','<<std::fixed<<std::setprecision(3)<<timestamp<<','<<t.id<<','<<typeName(t.category)<<','<<csvText(t.plateVisible&&t.plateStable?t.plate.text:std::string())<<','<<csvText(t.plateVisible&&t.plateStable?characters(t.plate.text):std::string())<<','<<csvText(t.plateVisible&&t.plateStable?numbers(t.plate.text):std::string())<<','<<t.plate.confidence<<','<<t.confidence<<','<<(t.plateStable&&t.plateVisible?1:0)<<','<<plateStatus(t)<<','<<t.plateSource<<','<<t.lastPlateSeen<<','<<csvText(t.plate.text)<<','<<t.lastSeen<<','<<t.reacquisitions<<'\n';
  bool present=elapsed+.0005>=nextPreview;if(present){nextPreview+=1./o.fps;if(nextPreview<elapsed-1./o.fps)nextPreview=elapsed+1./o.fps;++previewFrames;}
  if(o.allowTextCandidates)cv::putText(image,"SYNTHETIC TEXT TEST - NOT REAL PLATE VALIDATION",cv::Point(4,std::max(12,image.rows-8)),cv::FONT_HERSHEY_SIMPLEX,.5,cv::Scalar(0,200,255),1);
  draw(image,view,previewFrames/std::max(.001,elapsed));if(frames%60==0)cv::imwrite(o.output+"/annotated_sample.jpg",image);if(have&&!view.tracks().empty())cv::imwrite(o.output+"/active_sample.jpg",image);if(!o.record.empty()){if(!recording.isOpened()){recording.open(o.record,cv::VideoWriter::fourcc('M','J','P','G'),(o.offline?sourceFps:std::min(sourceFps,(double)o.fps)),image.size());if(!recording.isOpened())throw std::runtime_error("Cannot write recording; use an .avi path");}if(o.offline||present)recording.write(image);}
  ++frames;if(!o.headless&&present){cv::imshow("Car - vehicle and plate monitor",image);int key=cv::waitKey(1);if(key==27||key=='q')break;}
  if(!o.offline&&!camera)std::this_thread::sleep_until(start+std::chrono::milliseconds((long long)(frames*1000/sourceFps)));
 }
 double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::sort(latency.begin(),latency.end());double p95=latency.empty()?0:latency[(size_t)(.95*(latency.size()-1))];int dropped=worker?worker->dropped():0;worker.reset();recording.release();cap.release();if(!o.headless)cv::destroyAllWindows();
 std::ofstream metrics(o.output+"/performance.json");metrics<<"{\n  \"frames\": "<<frames<<", \"inferences\": "<<inferences<<", \"elapsed_seconds\": "<<seconds<<",\n  \"display_fps\": "<<previewFrames/std::max(.001,seconds)<<", \"inference_fps\": "<<inferences/std::max(.001,seconds)<<",\n  \"inference_p95_ms\": "<<p95<<", \"target_preview_fps\": "<<o.fps<<", \"dropped_pending_frames\": "<<dropped<<", \"stale_results\": "<<stale<<",\n  \"offline\": "<<(o.offline?"true":"false")<<", \"latency_budget_ms\": "<<o.maxAge*1000<<",\n  \"lighting_correction\": "<<(o.lighting?"true":"false")<<",\n  \"synthetic_text_mode\": "<<(o.allowTextCandidates?"true":"false")<<"\n}\n";
 std::cout<<"Frames="<<frames<<" inferences="<<inferences<<" processed_fps="<<frames/std::max(.001,seconds)<<" preview_fps="<<previewFrames/std::max(.001,seconds)<<" inference_p95_ms="<<p95<<" dropped="<<dropped<<" stale="<<stale<<"\n";return frames?0:2;
}
}
int main(int argc,char** argv){try{car::Options o;char executable[MAX_PATH];GetModuleFileNameA(NULL,executable,MAX_PATH);std::string root(executable);root=root.substr(0,root.find_last_of("\\/"))+"/../../";char absolute[MAX_PATH];GetFullPathNameA(root.c_str(),MAX_PATH,absolute,NULL);root=absolute;o.models=root+"models";o.output=root+"output";std::string action="run",directory=root+"testdata";for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--help"){std::cout<<"Car.exe [--source 0|video.avi] [--models models] [--output output] [--record output/view.avi]\n [--offline] [--headless] [--max-frames N] [--detector-every N] [--numbers-only] [--opencl]\n [--allow-text-candidates (synthetic tests only)] [--lighting auto|off] [--ocr-languages eng+chi_sim+kor+jpn|latin] [--confidence 0.3] [--max-age 0.5] [--threads 4] [--fps 15|30] [--directml|--cpu] [--gpu-device 0]\nCar.exe --generate-test testdata\nCar.exe --generate-lighting testdata\nCar.exe --generate-evidence testdata\nCar.exe --tracking-review output\tracking_review\nCar.exe --self-test [--models models]\n";return 0;}if(a=="--allow-text-candidates")o.allowTextCandidates=true;else if(a=="--headless")o.headless=true;else if(a=="--offline")o.offline=true;else if(a=="--numbers-only")o.numbersOnly=true;else if(a=="--opencl"){o.opencl=true;o.directml=false;}else if(a=="--directml"){o.directml=true;o.opencl=false;}else if(a=="--cpu"){o.directml=false;o.opencl=false;}else if(a=="--self-test")action="tests";else{if(i+1==argc)throw std::runtime_error("Missing value for "+a);std::string value=argv[++i];if(a=="--lighting"){if(value!="auto"&&value!="off")throw std::runtime_error("Lighting must be auto or off");o.lighting=value=="auto";}else if(a=="--tracking-review"){action="tracking_review";directory=value;}else if(a=="--generate-evidence"){action="evidence";directory=value;}else if(a=="--generate-lighting"){action="lighting";directory=value;}else if(a=="--ocr-languages")o.ocrLanguages=value;else if(a=="--source")o.source=value;else if(a=="--models")o.models=value;else if(a=="--output")o.output=value;else if(a=="--record")o.record=value;else if(a=="--max-frames")o.maxFrames=std::stoi(value);else if(a=="--detector-every")o.detectorEvery=std::stoi(value);else if(a=="--threads")o.threads=std::stoi(value);else if(a=="--fps")o.fps=std::stoi(value);else if(a=="--gpu-device")o.gpuDevice=std::stoi(value);else if(a=="--confidence")o.confidence=std::stof(value);else if(a=="--max-age")o.maxAge=std::stod(value);else if(a=="--generate-test"){action="generate";directory=value;}else throw std::runtime_error("Unknown option: "+a);}}
 if(o.maxFrames<0||o.detectorEvery<1||o.threads<1||o.fps<1||o.fps>120||!std::isfinite(o.maxAge)||!std::isfinite(o.confidence)||o.maxAge<=0||o.confidence<=0||o.confidence>=1)throw std::runtime_error("Invalid option value");cv::setNumThreads(o.threads);if(action=="tracking_review")return car::trackingReview(directory,o.models);if(action=="evidence")return car::generateEvidenceVideos(directory);if(action=="lighting")return car::generateLightingVideos(directory);if(action=="generate")return car::generateVideos(directory,o.models);if(action=="tests")return car::runTests(o.models);return car::run(o);
}catch(const std::exception& e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
